            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"160\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"230\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">WHERE THE ESSAYS CAME FROM</text><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">A collection, not a single treatise</text><text x=\"550\" y=\"325\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">One exception began as a lecture</text><rect x=\"200\" y=\"450\" width=\"700\" height=\"100\" rx=\"20\" fill=\"rgba(255,255,255,0.05)\" stroke=\"#888\" stroke-width=\"2\"/><text x=\"550\" y=\"512\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Novel? Journal? Newsletter? Column?</text><rect x=\"200\" y=\"620\" width=\"700\" height=\"100\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"682\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Think about the intended audience</text></svg>",
