            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"170\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"240\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">MORAL GRAYNESS</text><text x=\"550\" y=\"295\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Does gray abolish black and white?</text><text x=\"550\" y=\"335\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Or does it depend on them?</text><rect x=\"200\" y=\"460\" width=\"220\" height=\"180\" rx=\"20\" fill=\"rgba(255,255,255,0.05)\" stroke=\"#fff\" stroke-width=\"2\"/><rect x=\"440\" y=\"460\" width=\"220\" height=\"180\" rx=\"20\" fill=\"rgba(136,136,136,0.3)\" stroke=\"#888\" stroke-width=\"2\"/><rect x=\"680\" y=\"460\" width=\"220\" height=\"180\" rx=\"20\" fill=\"rgba(0,0,0,0.5)\" stroke=\"#888\" stroke-width=\"2\"/></svg>",
